import java.io.BufferedReader;import java.io.IOException;import java.io.InputStreamReader;import java.io.PrintWriter;public class Main {    public static void main(String[] args) throws IOException {        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));        PrintWriter pw = new PrintWriter(System.out);        String xStr = br.readLine();        StringBuilder result = new StringBuilder();        for (int i = 0; i < xStr.length(); i++) {            int digit = xStr.charAt(i) - '0';            if (i == 0) {                if (digit == 9) {                    result.append('9');                } else {                    result.append(Math.min(digit, 9 - digit));                }            } else {                result.append(Math.min(digit, 9 - digit));            }        }        pw.println(result.toString());        pw.flush();        pw.close();        br.close();    }}